import{_ as e,c as a,o as t,f as i}from"./chunks/framework.BOAZPCR7.js";const _=JSON.parse('{"title":"Mutational constraints on RSV F and its neutralization by antibodies","description":"","frontmatter":{"layout":"paper","title":"Mutational constraints on RSV F and its neutralization by antibodies","date":"2026-09-16","authors":["Cassandra AL Simonich","Teagan E McMahon","Gavin Juviler","Lucas Kampman","Helen Y Chu","Jesse D Bloom"],"journal":"Nature","doi":"10.1038/s41586-026-11030-4","link":"https://www.nature.com/articles/s41586-026-11030-4","image":"/assets/papers/2026_simonich_dms.png","keywords":["RSV","Deep mutational scanning","Pseudovirus"],"selected":true,"head":[["link",{"rel":"canonical","href":"https://jbloomlab.org/papers/2026_simonich_dms.html"}]]},"headers":[],"relativePath":"papers/2026_simonich_dms.md","filePath":"papers/2026_simonich_dms.md"}'),n={name:"papers/2026_simonich_dms.md"},s=i('<h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>New antibodies targeting the F protein of respiratory syncytial virus (RSV) have substantially reduced infant hospitalizations. However, viral resistance is a concern: one antibody failed clinical trials because of a resistant strain, and sporadic resistance mutations to the most widely used antibody (nirsevimab) have been identified. Here we define how RSV F mutations affect antibody neutralization. We first provide a biophysical model of how the buffering of bivalent IgG binding combines with the lower Fab potency of nirsevimab to subtype B to make resistance to this antibody more common in subtype B than A strains. We then perform pseudovirus deep mutational scanning to safely measure how nearly all mutations to F affect its cell entry function and neutralization by IgG and Fab forms of nirsevimab, clesrovimab and several other key antibodies. We use these measurements to enable real-time surveillance of RSV sequences for antibody resistance, and show that resistant strains have arisen sporadically but are at present rare. Overall, our work shows how Fab potency and epitope specificity combine to determine how viral mutations affect antibody neutralization, enables monitoring for natural RSV strains resistant to antibodies of public-health importance, and can help guide development of future antibodies with resilience to viral escape.</p><h2 id="interactive-visualizations" tabindex="-1">Interactive visualizations <a class="header-anchor" href="#interactive-visualizations" aria-label="Permalink to &quot;Interactive visualizations&quot;">​</a></h2><p>The results described in this paper can be interactively visualized at <a href="https://dms-vep.org/RSV_Long_F_DMS/" target="_blank" rel="noreferrer">https://dms-vep.org/RSV_Long_F_DMS/</a>; all computer code and data is at <a href="https://github.com/dms-vep/RSV_Long_F_DMS" target="_blank" rel="noreferrer">https://github.com/dms-vep/RSV_Long_F_DMS</a>.</p>',4),o=[s];function r(l,c,d,h,m,p){return t(),a("div",null,o)}const b=e(n,[["render",r]]);export{_ as __pageData,b as default};
